body.script:
(function(){
  var NS = 'http://www.w3.org/1999/xhtml';
  function $(i){ return document.getElementById(i); }
  var body = document.body;
  var search = $('search'), count = $('count'), empty = $('empty'), toast = $('toast'), sheet = $('sheet'), sheetUrl = $('sheetUrl');
  var settings = $('settings'), settingsOpen = $('settingsOpen'), settingsClose = $('settingsClose');
  var groups = [].slice.call(document.querySelectorAll('.group'));

  // ── helpers
  function say(m){
    if(!toast) return;
    toast.textContent = m; toast.classList.add('show');
    clearTimeout(say.t); say.t = setTimeout(function(){ toast.classList.remove('show'); }, 1400);
  }
  function flash(b){
    b.textContent = 'copied'; b.classList.add('ok');
    clearTimeout(flash.t); flash.t = setTimeout(function(){ b.textContent = 'copy'; b.classList.remove('ok'); }, 1100);
  }
  function manual(t){
    if(!sheet) return;
    sheetUrl.value = t; sheet.classList.add('show');
    sheetUrl.focus(); sheetUrl.select();
    try{ sheetUrl.setSelectionRange(0, t.length); }catch(e){}
  }
  function copy(t, b){
    var ok = function(){ flash(b); say('copied'); };
    try {
      if(navigator.clipboard && navigator.clipboard.writeText){
        navigator.clipboard.writeText(t).then(ok, function(){ manual(t); });
      } else { manual(t); }
    } catch(e){ manual(t); }
  }

  // ── settings open/close
  if(settingsOpen){ settingsOpen.addEventListener('click', function(){ settings.classList.toggle('open'); }); }
  if(settingsClose){ settingsClose.addEventListener('click', function(){ settings.classList.remove('open'); }); }
  if($('sheetX')){ $('sheetX').addEventListener('click', function(){ sheet.classList.remove('show'); }); }

  // ── copy buttons (injected)
  [].forEach.call(document.querySelectorAll('.acts'), function(box){
    var t = box.parentNode.querySelector('.u').textContent;
    var b = document.createElementNS(NS, 'button');
    b.setAttribute('type', 'button'); b.setAttribute('class', 'btn'); b.textContent = 'copy';
    b.addEventListener('click', function(e){ e.preventDefault(); e.stopPropagation(); copy(t, b); });
    box.insertBefore(b, box.firstChild);
  });

  // ── THEME
  var swatches = [].slice.call(document.querySelectorAll('.sw'));
  var themeLabel = $('themeLabel');
  var savedTheme = 'purple';
  try { savedTheme = localStorage.getItem('pi-theme') || 'purple'; } catch(e){}
  function setTheme(t){
    body.setAttribute('data-t', t);
    swatches.forEach(function(s){ s.setAttribute('aria-pressed', String(s.getAttribute('data-s') === t)); });
    if(themeLabel) themeLabel.textContent = t;
    try { localStorage.setItem('pi-theme', t); } catch(e){}
  }
  setTheme(savedTheme);
  swatches.forEach(function(s){
    s.addEventListener('click', function(e){ e.preventDefault(); setTheme(s.getAttribute('data-s')); });
  });

  // ── WALLPAPER — replace these with the actual image URLs you want
  var WALLS = [
    '',                                                         // none
    'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=1920&q=80', // purple moody
    'https://images.unsplash.com/photo-1522778119026-d647f0596c20?w=1920&q=80', // stadium
    'https://images.unsplash.com/photo-1544636331-e26879cd4d9b?w=1920&q=80',    // lambo yellow
    'https://images.unsplash.com/photo-1503376780353-7e6692767b70?w=1920&q=80'  // black supercar night
  ];
  function setWall(idx){
    if(idx < 0 || idx >= WALLS.length) idx = 0;
    if(!WALLS[idx]){
      body.style.setProperty('--wall','none');
    } else {
      body.style.setProperty('--wall', "url('" + WALLS[idx] + "')");
    }
    try { localStorage.setItem('pi-wall', String(idx)); } catch(e){}
    [].forEach.call(document.querySelectorAll('.wallbtn'), function(b){
      b.setAttribute('aria-pressed', String(parseInt(b.getAttribute('data-w'),10) === idx));
    });
  }
  var savedWall = 0;
  try { savedWall = parseInt(localStorage.getItem('pi-wall') || '0',10); if(isNaN(savedWall)) savedWall = 0; } catch(e){}
  setWall(savedWall);
  [].forEach.call(document.querySelectorAll('.wallbtn'), function(b){
    b.addEventListener('click', function(e){ e.preventDefault(); setWall(parseInt(b.getAttribute('data-w'),10)); });
  });

  // brightness / blur
  var wallDim = $('wallDim'), dimVal = $('dimVal');
  var wallBlurR = $('wallBlurRange'), blurVal = $('blurVal');
  function applyDim(v){
    v = Math.max(20, Math.min(100, v|0));
    body.style.setProperty('--wall-dim', String(v/100));
    if(dimVal) dimVal.textContent = v + '%';
    if(wallDim) wallDim.value = v;
    try{ localStorage.setItem('pi-dim', String(v)); }catch(e){}
  }
  function applyBlur(v){
    v = Math.max(0, Math.min(40, v|0));
    body.style.setProperty('--wall-blur', v + 'px');
    if(blurVal) blurVal.textContent = v + 'px';
    if(wallBlurR) wallBlurR.value = v;
    try{ localStorage.setItem('pi-blur', String(v)); }catch(e){}
  }
  var sv = 88, sb = 22;
  try { sv = parseInt(localStorage.getItem('pi-dim') || '88',10); if(isNaN(sv)) sv = 88; } catch(e){}
  try { sb = parseInt(localStorage.getItem('pi-blur') || '22',10); if(isNaN(sb)) sb = 22; } catch(e){}
  applyDim(sv); applyBlur(sb);
  if(wallDim){ wallDim.addEventListener('input', function(){ applyDim(parseInt(wallDim.value,10)); }); }
  if(wallBlurR){ wallBlurR.addEventListener('input', function(){ applyBlur(parseInt(wallBlurR.value,10)); }); }

  // motion
  var wallMove = $('wallMove');
  var moveOn = true;
  try { moveOn = (localStorage.getItem('pi-move') || '1') === '1'; } catch(e){}
  function applyMove(){
    body.setAttribute('data-move', moveOn ? '1' : '0');
    if(wallMove) wallMove.setAttribute('aria-checked', String(moveOn));
    try { localStorage.setItem('pi-move', moveOn ? '1' : '0'); } catch(e){}
  }
  applyMove();
  if(wallMove){ wallMove.addEventListener('click', function(e){ e.preventDefault(); moveOn = !moveOn; applyMove(); }); }

  // ── SNOWFALL
  var snowBtn = $('snowBtn'), snowFx = $('snowFx');
  var snowOn = false;
  try { snowOn = (localStorage.getItem('pi-snow') || '0') === '1'; } catch(e){}
  function buildSnow(){
    if(!snowFx) return;
    snowFx.innerHTML = '';
    for(var i=0;i<60;i++){
      var p = document.createElementNS(NS, 'i');
      var left = Math.random() * 100;
      var dur = 6 + Math.random() * 10;
      var delay = -Math.random() * dur;
      var dx = (Math.random() * 40 - 20);
      var size = 3 + Math.random() * 4;
      p.setAttribute('style',
        'left:' + left + '%;' +
        'width:' + size + 'px;height:' + size + 'px;' +
        '--dx:' + dx + 'px;' +
        'animation-duration:' + dur + 's;' +
        'animation-delay:' + delay + 's;');
      snowFx.appendChild(p);
    }
  }
  function applySnow(){
    body.setAttribute('data-snow', snowOn ? '1' : '0');
    if(snowBtn) snowBtn.setAttribute('aria-checked', String(snowOn));
    try { localStorage.setItem('pi-snow', snowOn ? '1' : '0'); } catch(e){}
    if(snowOn && snowFx && !snowFx.childNodes.length) buildSnow();
  }
  applySnow();
  if(snowBtn){ snowBtn.addEventListener('click', function(e){ e.preventDefault(); snowOn = !snowOn; applySnow(); }); }

  // ── GLITCH
  var glitchBtn = $('glitchBtn');
  var glitchOn = false;
  try { glitchOn = (localStorage.getItem('pi-glitch') || '0') === '1'; } catch(e){}
  function applyGlitch(){
    body.setAttribute('data-glitch', glitchOn ? '1' : '0');
    if(glitchBtn) glitchBtn.setAttribute('aria-checked', String(glitchOn));
    try { localStorage.setItem('pi-glitch', glitchOn ? '1' : '0'); } catch(e){}
  }
  applyGlitch();
  if(glitchBtn){ glitchBtn.addEventListener('click', function(e){ e.preventDefault(); glitchOn = !glitchOn; applyGlitch(); }); }

  // ── CLOAK (about:blank)
  var cloakBtn = $('cloakBtn');
  if(cloakBtn){
    cloakBtn.addEventListener('click', function(e){
      e.preventDefault();
      var current = window.location.href;
      var win = window.open('about:blank', '_blank');
      if(!win){ say('popup blocked'); return; }
      try {
        var doc = win.document;
        doc.title = '';
        doc.body.style.cssText = 'margin:0;overflow:hidden;background:#000;height:100vh';
        var ifr = doc.createElement('iframe');
        ifr.src = current;
        ifr.style.cssText = 'position:fixed;inset:0;width:100vw;height:100vh;border:0;background:#000';
        ifr.setAttribute('allowfullscreen','');
        doc.body.appendChild(ifr);
        say('cloaked');
      } catch(err){
        try { win.location.href = current; } catch(e2){}
      }
      cloakBtn.setAttribute('aria-checked', 'true');
      setTimeout(function(){ cloakBtn.setAttribute('aria-checked', 'false'); }, 900);
    });
  }

  // ── SEARCH
  function update(){
    if(!search) return;
    var q = (search.value || '').trim().toLowerCase(), g = 0, l = 0;
    groups.forEach(function(grp){
      var hitName = !q || grp.querySelector('.gn').textContent.toLowerCase().indexOf(q) > -1, n = 0;
      [].forEach.call(grp.querySelectorAll('.li'), function(it){
        var hit = hitName || it.querySelector('.u').textContent.toLowerCase().indexOf(q) > -1;
        it.classList.toggle('hidden', !hit); if(hit) n++;
      });
      var pill = grp.querySelector('.pill'); if(pill) pill.textContent = n;
      grp.classList.toggle('hidden', !n);
      if(q && n) grp.open = true;
      if(n){ g++; l += n; }
    });
    if(count) count.innerHTML = '<b>' + g + '</b> groups, <b>' + l + '</b> links';
    if(empty) empty.classList.toggle('show', !g);
  }
  if(search){ search.addEventListener('input', update); }
  document.addEventListener('keydown', function(e){
    if(e.key === '/' && document.activeElement !== search && search){ e.preventDefault(); search.focus(); search.select(); }
    else if(e.key === 'Escape'){ if(settings) settings.classList.remove('open'); if(sheet) sheet.classList.remove('show'); if(search && search.value){ search.value = ''; update(); } }
  });

  // build snow once so it's ready
  buildSnow();
})();
